From a671a7a8b94744df46f11934036ef1f9d5abdd17 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:07:37 +0100
Subject: [PATCH] KPropertiesDialog: show the real location of items on
 desktop:/

Items in desktop:/ had their Location shown as "/ (desktop)", the path
of the virtual URL, even though the worker maps them to local files. Use
the local folder instead when the item has one, except for the trash.

BUG: 412670
---
 src/widgets/kpropertiesdialogbuiltin_p.cpp | 16 +++++++++++-----
 1 file changed, 11 insertions(+), 5 deletions(-)

diff --git a/src/widgets/kpropertiesdialogbuiltin_p.cpp b/src/widgets/kpropertiesdialogbuiltin_p.cpp
index 0a56e9a59..0274c1a2b 100644
--- a/src/widgets/kpropertiesdialogbuiltin_p.cpp
+++ b/src/widgets/kpropertiesdialogbuiltin_p.cpp
@@ -222,8 +222,14 @@ KFilePropsPlugin::KFilePropsPlugin(KPropertiesDialog *_props)
     bool hasDirs = firstItem.isDir() && !firstItem.isLink();
     bool hasRoot = url.path() == QLatin1String("/");
     QString iconStr = firstItem.iconName();
-    QString directory = properties->url().adjusted(QUrl::RemoveFilename | QUrl::StripTrailingSlash).path();
     QString protocol = properties->url().scheme();
+    const bool showLocalDirectory = isLocal && protocol != QLatin1String("trash");
+    const auto locationOf = [showLocalDirectory](const KFileItem &item) {
+        const auto [itemUrl, itemIsLocal] = item.isMostLocalUrl();
+        const QUrl dirUrl = (showLocalDirectory && itemIsLocal ? itemUrl : item.url()).adjusted(QUrl::RemoveFilename | QUrl::StripTrailingSlash);
+        return dirUrl.isLocalFile() ? dirUrl.toLocalFile() : dirUrl.path();
+    };
+    QString directory = locationOf(firstItem);
     d->bKDesktopMode = protocol == QLatin1String("desktop") || properties->currentDir().scheme() == QLatin1String("desktop");
     QString mimeComment = firstItem.mimeComment();
     d->mimeType = firstItem.mimetype();
@@ -246,8 +252,8 @@ KFilePropsPlugin::KFilePropsPlugin(KPropertiesDialog *_props)
         }
     }
 #ifdef Q_OS_WIN
-    if (isReallyLocal) {
-        directory = QDir::toNativeSeparators(directory.mid(1));
+    if (isReallyLocal || showLocalDirectory) {
+        directory = QDir::toNativeSeparators(directory);
     }
 #endif

@@ -316,7 +322,7 @@ KFilePropsPlugin::KFilePropsPlugin(KPropertiesDialog *_props)
             if (KIO::iconNameForUrl(url) != iconStr) {
                 iconStr = QStringLiteral("document-multiple");
             }
-            if (url.adjusted(QUrl::RemoveFilename | QUrl::StripTrailingSlash).path() != directory) {
+            if (locationOf(item) != directory) {
                 directory.clear();
             }
             if (url.scheme() != protocol) {
@@ -347,7 +353,7 @@ KFilePropsPlugin::KFilePropsPlugin(KPropertiesDialog *_props)
         }
     }

-    if (!isReallyLocal && !protocol.isEmpty()) {
+    if (!isReallyLocal && !showLocalDirectory && !protocol.isEmpty()) {
         directory += QLatin1String(" (") + protocol + QLatin1Char(')');
     }

